  orders:
    <<: [*node, *logging]
    image: shopflow/orders:dev
    build: { context: ., dockerfile: services/orders/Dockerfile }
    environment:
      SERVICE_NAME: orders
      ORDERS_DB_HOST: orders-db
      ORDERS_DB_USER: app
      ORDERS_DB_PASSWORD: ${ORDERS_APP_DB_PASSWORD:-orders-secret}
      ORDERS_DB_POOL_MAX: ${ORDERS_DB_POOL_MAX:-10}
      NATS_URL: nats://event-bus:4222
      CART_URL: http://cart:3002
      INVENTORY_URL: http://inventory:3003
      PAYMENTS_URL: http://payments:3004
      PAYMENTS_RETRY_MAX: ${ORDERS_PAYMENTS_RETRY_MAX:-1}
      PAYMENTS_RETRY_BACKOFF_MS: ${ORDERS_PAYMENTS_RETRY_BACKOFF_MS:-250}
      DB_CONNECT_RETRIES: ${DB_CONNECT_RETRIES:-30}
      ORDER_EVENT_SCHEMA: ${ORDER_EVENT_SCHEMA:-1}
    depends_on:
      orders-db: { condition: service_healthy }
      event-bus: { condition: service_started }
      cart: { condition: service_started }
      inventory: { condition: service_started }
      payments: { condition: service_started }
    mem_limit: 256m

  orders-db:
    image: postgres:16-alpine
    restart: always
    environment:
      POSTGRES_USER: app
      POSTGRES_PASSWORD: ${ORDERS_DB_PASSWORD:-orders-secret}
      POSTGRES_DB: orders
      SEED_ORDERS: ${SEED_ORDERS:-5000}
    volumes: ["./db/orders-db:/docker-entrypoint-initdb.d:ro", "orders-db-data:/var/lib/postgresql/data"]
    healthcheck: { test: ["CMD-SHELL", "pg_isready -h 127.0.0.1 -U app -d orders"], interval: 5s, timeout: 3s, retries: 60 }
    mem_limit: 1g
    <<: *logging

  event-bus:
#!/bin/bash
# Schema + historical data. SEED_ORDERS sets how much history the database already holds.
# Staging typically has a few thousand rows; a year-old production database has millions.
set -euo pipefail
ROWS="${SEED_ORDERS:-5000}"
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" <<SQL
create table orders (
  id uuid primary key, user_id text not null, email text not null, total_cents int not null,
  status text not null, items jsonb not null, created_at timestamptz not null default now()
);
-- Lookups by id are covered by the primary key. History is read per user, newest first.
insert into orders(id, user_id, email, total_cents, status, items, created_at)
select gen_random_uuid(), 'hist-' || (g % 200000), 'hist-' || (g % 200000) || '@example.test', 1000 + g % 9000, 'paid',
       '[{"productId":1,"qty":1,"priceCents":1000}]'::jsonb, now() - (g || ' seconds')::interval
from generate_series(1, ${ROWS}) g;
analyze orders;
SQL
id: sf-05-secret-rotation
title: Rotated database password; one service still has the old one
class: deployment / configuration drift
verified: docker
summary: >
  The orders database password was rotated. orders-db has the new password, but the orders deployment still carries the old
  secret. orders retries the connection 5 times, logs the error, exits 1, and the restart policy brings it back -- forever.
  The container is "running" for a few seconds out of every cycle, so a casual `docker ps` can look alive.
why_code_review_and_tests_pass: "No code changed. The failure is entirely in the gap between two deployments."
production_condition: "ORDERS_DB_PASSWORD (app side) != POSTGRES_PASSWORD (db side)"
load: { command: "node lab/loadgen.mjs shopflow --concurrency 10 --duration 180 --users 200" }
ground_truth: { root_cause: orders, symptomatic: [api-gateway, notifier], note: "orders is the failing service; orders-db is healthy" }
mapper_signals:
  - { signal: "orders status exited/restarting, restartCount climbing", where: container state, strength: strong }
  - { signal: "orders -> orders-db edge is DECLARED (compose) but never OBSERVED", where: edge, strength: strong, note: "the canonical declared-vs-observed case; orders-db itself is healthy" }
  - { signal: "gateway 502 on /api/orders and /api/checkout; /api/catalog unaffected", where: Tier-1 gateway log, strength: strong }
  - { signal: "notifier -> orders edge disappears (nothing to fetch), event-bus idle", where: edge, strength: partial }
mapper_blind_spots:
  - "Does not know WHY orders cannot connect (password vs network vs DNS). It narrows it to 'orders cannot reach a healthy orders-db'; the container's own log says 'password authentication failed'."
expect:
  edges:
    - { source: orders, target: orders-db, declared: true, observed: false }
  nodes_unhealthy_at_some_point: [orders]
  incident: { root_cause_any_of: [orders] }
fix: "roll the secret to orders; make secret rotation a single atomic deploy; alert on restart loops"
measured_in_docker:    # real postgres:16 with scram auth
  orders_restarts_in_45s: 7
  orders_log: 'password authentication failed for user "app"'
  orders_db_health: healthy
  gateway: { "/api/catalog": 200, "/api/orders": 502 }

