export type IncidentStatus = 'NORMAL' | 'DEGRADED' | 'INCIDENT' | 'RECOVERING' | 'RESOLVED';
export type IncidentSeverity = 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
export type RCAConfidence = 'HIGH' | 'MEDIUM' | 'LOW' | 'UNKNOWN';

export interface AnomalyRecord {
  id: string;
  nodeId: string;
  targetId: string;
  metric: string;
  timestamp: string;
  observedValue: number;
  baselineMean: number;
  baselineStdDev: number;
  zScore: number;
  severity: IncidentSeverity;
  evidenceSource?: string;
}

export interface PropagationStep {
  sourceId: string;
  targetId: string;
  timestamp: string;
  edgeId: string;
  evidenceSource: string;
  metricChange: string;
  confidence: RCAConfidence;
}

export interface ScoreContribution {
  factor: string;
  score: number;
  reason: string;
}

export interface CandidateCause {
  serviceId: string;
  serviceName: string;
  score: number; // 0.0 - 1.0
  confidence: RCAConfidence;
  scoreBreakdown: ScoreContribution[];
  earliestAnomalyTimestamp?: string;
  primaryAnomalyMetric?: string;
}

export interface EvidenceItem {
  id: string;
  metric: string;
  timestamp: string;
  beforeValue: string;
  afterValue: string;
  changePercentage?: string;
  source: string; // e.g., 'HTTP telemetry', 'container-runtime', 'network-tcp'
  description: string;
}

export interface RCAExplanation {
  whatHappened: string;
  whenStarted: string;
  likelyRootCause: string;
  why: string;
import type { AnomalyRecord } from '../models/Incident.js';

export interface TemporalTimelinePoint {
  timestamp: string;
  nodeId: string;
  metric: string;
  zScore: number;
  observedValue: number;
  isEarliest: boolean;
}

export class TemporalAnalyzer {
  public buildTimeline(anomalies: AnomalyRecord[]): TemporalTimelinePoint[] {
    if (anomalies.length === 0) return [];

    // Sort anomalies chronologically by timestamp
    const sorted = [...anomalies].sort((a, b) => 
      new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
    );

    const earliestMs = new Date(sorted[0].timestamp).getTime();

    return sorted.map((a) => {
      const aMs = new Date(a.timestamp).getTime();
      return {
        timestamp: a.timestamp,
        nodeId: a.nodeId,
        metric: a.metric,
        zScore: a.zScore,
        observedValue: a.observedValue,
        isEarliest: Math.abs(aMs - earliestMs) < 1000 // within 1 second of first anomaly
      };
    });
  }

  public findEarliestAnomalousNode(anomalies: AnomalyRecord[]): string | null {
    const timeline = this.buildTimeline(anomalies);
    const earliest = timeline.find(p => p.isEarliest);
    return earliest ? earliest.nodeId : null;
  }
}
  return LIMITS;
}

